/**
 * Whether the dashboard should ask the API now: only while its tab is visible and the operator has
 * touched it (a key, the pointer, a scroll) within `IDLE_MS`. Polling and live streams pause otherwise
 * and resume at the next touch, so a tab left open asks nothing: on Cloudflare every read is a request
 * of the day's budget (100,000 for the Worker and as many for the Durable Objects on the Free plan),
 * shared with the bot.
 *
 * On Cloudflare (`ApiApp.target` `durable`) polling is also slower (`every`): each list read calls the
 * index and every conversation's object.
 */

import { useEffect, useRef, useSyncExternalStore } from "react";

/** Without a touch for this long, the dashboard stops asking. */
export const IDLE_MS = 5 * 60_000;
/** Polling is this many times slower on Cloudflare. */
export const CLOUDFLARE_SLOWER = 3;

const TOUCHES = ["pointerdown", "pointermove", "keydown", "wheel", "touchstart", "focus"] as const;

let last = Date.now();
let timer: ReturnType<typeof setTimeout> | undefined;
let target = "server";
const listeners = new Set<() => void>();

const compute = (): boolean => document.visibilityState === "visible" && Date.now() - last < IDLE_MS;
let active = compute();

function update(): void {
  const next = compute();
  if (next === active) return;
  active = next;
  for (const listener of listeners) listener();
}

function touch(): void {
  // The pointer moves often: once a second is enough.
  if (active && Date.now() - last < 1000) return;
  last = Date.now();
  update();
  clearTimeout(timer);
  timer = setTimeout(update, IDLE_MS + 100);
}

for (const name of TOUCHES) window.addEventListener(name, touch, { passive: true, capture: true });
document.addEventListener("visibilitychange", () => (document.visibilityState === "visible" ? touch() : update()));
timer = setTimeout(update, IDLE_MS + 100);

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether the tab is visible and the operator was there within `IDLE_MS`. */
export function useActive(): boolean {
  return useSyncExternalStore(subscribe, () => active);
}

/** Where the App runs (`ApiApp.target`), which the shell says once it read the composition. */
export function setTarget(value: string): void {
  target = value;
}

/** `ms` for this host: slower on Cloudflare. */
export function every(ms: number): number {
  return target === "durable" ? ms * CLOUDFLARE_SLOWER : ms;
}

/**
 * Calls `tick` every `everyMs` while the dashboard is active (`useActive`), and at once when it
 * becomes active again after a pause. `undefined` polls nothing. Returns whether it is active.
 */
export function usePolling(tick: () => void, everyMs: number | undefined): boolean {
  const isActive = useActive();
  const saved = useRef(tick);
  saved.current = tick;
  const wasActive = useRef(isActive);

  useEffect(() => {
    if (everyMs === undefined || !isActive) {
      wasActive.current = isActive;
      return;
    }
    if (!wasActive.current) saved.current();
    wasActive.current = true;
    const interval = setInterval(() => saved.current(), everyMs);
    return () => clearInterval(interval);
  }, [isActive, everyMs]);

  return isActive;
}

/** Small formatting helpers shared by views. */

/** A cost in dollars: `$0.0042`, `$1.23`, from a usage's total (`ApiUsage` is one). */
export function formatCost(usage: { cost: { total: number } } | undefined): string {
  const total = usage?.cost.total ?? 0;
  if (total === 0) return "$0";
  return `$${total < 0.01 ? total.toFixed(4) : total.toFixed(2)}`;
}

/** Tokens, short: `950`, `12.3k`, `1.2M`. */
export function formatTokens(count: number): string {
  if (count < 1000) return String(count);
  if (count < 1_000_000) return `${(count / 1000).toFixed(1)}k`;
  return `${(count / 1_000_000).toFixed(1)}M`;
}

const relative = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" });

/** `3 minutes ago`, from epoch milliseconds. */
export function formatAgo(at: number | undefined, now = Date.now()): string {
  if (at === undefined) return "—";
  const seconds = Math.round((at - now) / 1000);
  const steps: [Intl.RelativeTimeFormatUnit, number][] = [
    ["second", 60],
    ["minute", 60],
    ["hour", 24],
    ["day", 30],
    ["month", 12],
  ];
  let value = seconds;
  for (const [unit, size] of steps) {
    if (Math.abs(value) < size) return relative.format(value, unit);
    value = Math.round(value / size);
  }
  return relative.format(value, "year");
}

/**
 * A label's first letter in capitals, the rest as written (`possibly twice` → `Possibly twice`): how a
 * table's states and tags read. Anything but a string (an element) is left alone.
 */
export function capitalizeFirst<T>(label: T): T | string {
  return typeof label === "string" && label !== "" ? label.charAt(0).toLocaleUpperCase() + label.slice(1) : label;
}

/**
 * A transcript's messages in pi-ai's JSON (the runtime's own words, SPEC §5), as the API gives them,
 * and a tool running now: the types `components/pikit/message.tsx` shows and `transcript.ts` folds.
 * Types, `OPERATOR_NOTE` and `imageSrc`.
 */

/**
 * How every message from the dashboard starts, as the agent reads it: admin-api's `OPERATOR_NOTE`
 * (`admin-api.ts`), here too so the shared pieces need no admin client. The kit's tests check they are
 * the same.
 */
export const OPERATOR_NOTE = "[From the operator, in the pikit dashboard";

export type Text = { type: "text"; text: string };
export type Thinking = { type: "thinking"; thinking: string; redacted?: boolean };
/** An image: its bytes inline (base64), or where to read it (a page that serves its images by URL, as channel-web's chat does). */
export type Image = { type: "image"; mimeType: string; data: string } | { type: "image"; url: string; mimeType?: string };
export type ToolCall = { type: "toolCall"; id: string; name: string; arguments: Record<string, unknown> };

export type Message =
  | { role: "system"; content?: unknown; timestamp?: number }
  | { role: "user"; content: string | (Text | Image)[]; timestamp?: number }
  | { role: "assistant"; content: (Text | Thinking | ToolCall)[]; stopReason?: string; errorMessage?: string; timestamp?: number }
  | { role: "toolResult"; toolCallId: string; toolName: string; content: (Text | Image)[]; isError?: boolean; timestamp?: number };

export type UserMessage = Extract<Message, { role: "user" }>;
export type AssistantMessage = Extract<Message, { role: "assistant" }>;
export type ToolResultMessage = Extract<Message, { role: "toolResult" }>;

/** What an `<img>` shows of `image`: its URL, or its bytes as a `data:` URL. */
export const imageSrc = (image: Image): string => ("url" in image ? image.url : `data:${image.mimeType};base64,${image.data}`);

/** A tool running now, from the live events (`transcript.ts`). */
export interface RunningTool {
  callId: string;
  name: string;
  output: string;
}

/** How the dashboard shows names: no imports, so the kit's tests read it as it is. */

/**
 * An agent's name as the dashboard shows it (the stored name stays as it is): its words, split at
 * `-` and `_`, the first one capitalized. `assistant` is "Assistant", `support-bot` "Support bot".
 */
export function assistantName(name: string): string {
  const words = name.split(/[-_]+/).filter((word) => word !== "").join(" ");
  return words === "" ? name : words.charAt(0).toLocaleUpperCase() + words.slice(1);
}

/**
 * Interaction sounds (Beautiful UI's InteractionSounds, MIT: see NOTICE): one quiet cue per click on
 * anything interactive, synthesized with @web-kits/audio. On by default; the operator turns them off
 * in the workspace menu, remembered in this browser (`localStorage["pikit-sounds"]`). Nothing makes
 * an AudioContext before the first click.
 *
 * An element picks its cue with `data-sound="press|tick|release|page|pulse"`; inside
 * `[data-sound-silent]` nothing sounds.
 */

import { defineSound, ensureReady, type PlayOptions, setMasterVolume, type VoiceHandle } from "@web-kits/audio";
import { useSyncExternalStore } from "react";

const KEY = "pikit-sounds";

const INTERACTIVE_SELECTOR = [
  "button",
  "a[href]",
  "input:not([type='hidden'])",
  "select",
  "textarea",
  "summary",
  "[role='button']",
  "[role='checkbox']",
  "[role='menuitem']",
  "[role='menuitemcheckbox']",
  "[role='menuitemradio']",
  "[role='option']",
  "[role='radio']",
  "[role='switch']",
  "[role='tab']",
].join(",");

const DISMISS_WORDS = /close|dismiss|remove|delete|collapse|cancel|clear|stop|abort|reset/i;
const PRIMARY_WORDS = /send|save|submit|start|sign in|create|add/i;

type Cue = "press" | "tick" | "release" | "page" | "pulse";
type Play = (options?: PlayOptions) => VoiceHandle;

/** Five short cues, built on the first click (a browser allows audio only after a gesture). */
function buildCues(): Record<Cue, Play> {
  return {
    // most buttons: a crisp transient blended with a bright pluck
    press: defineSound({
      layers: [
        { source: { type: "noise", color: "white" }, filter: { type: "highpass", frequency: 2400 }, envelope: { attack: 0.0003, decay: 0.009, sustain: 0 }, gain: 0.13 },
        { source: { type: "sine", frequency: 680 }, envelope: { attack: 0.0006, decay: 0.022, sustain: 0, release: 0.008 }, gain: 0.24 },
      ],
    }),
    // toggles, tabs, inputs: a light tick
    tick: defineSound({
      source: { type: "square", frequency: 2100 },
      filter: { type: "bandpass", frequency: 2600, resonance: 1.6 },
      envelope: { attack: 0.0004, decay: 0.028, sustain: 0 },
      gain: 0.24,
    }),
    // close, delete, cancel: a light clack
    release: defineSound({
      source: { type: "noise", color: "white" },
      filter: { type: "lowpass", frequency: 1600, resonance: 0.9 },
      envelope: { attack: 0.001, decay: 0.055, sustain: 0 },
      gain: 0.32,
    }),
    // links, navigation: a soft upward blip
    page: defineSound({
      source: { type: "sine", frequency: { start: 430, end: 640 } },
      envelope: { attack: 0.002, decay: 0.11, sustain: 0, release: 0.03 },
      gain: 0.4,
    }),
    // primary actions: a rounder pulse
    pulse: defineSound({
      source: { type: "sine", frequency: 330 },
      filter: { type: "lowpass", frequency: 2200 },
      envelope: { attack: 0.002, decay: 0.13, sustain: 0, release: 0.04 },
      gain: 0.5,
    }),
  };
}

function cueFor(element: Element): Cue {
  const override = element.getAttribute("data-sound");
  if (override === "press" || override === "tick" || override === "release" || override === "page" || override === "pulse") return override;
  const label = `${element.getAttribute("aria-label") ?? ""} ${element.textContent ?? ""}`.trim();
  if (DISMISS_WORDS.test(label)) return "release";
  if (element.matches("input[type='checkbox'], input[type='radio'], select, [role='checkbox'], [role='radio'], [role='switch'], [role='tab'], [aria-pressed]")) return "tick";
  if (element.matches("a[href]")) return "page";
  if (PRIMARY_WORDS.test(label)) return "pulse";
  if (element.matches("input, textarea")) return "tick";
  return "press";
}

function storedOn(): boolean {
  try {
    return localStorage.getItem(KEY) !== "off";
  } catch {
    return true;
  }
}

let on = storedOn();
let cues: Record<Cue, Play> | undefined;
const listeners = new Set<() => void>();

function onClick(event: MouseEvent): void {
  if (!on || !(event.target instanceof Element)) return;
  const control = event.target.closest(INTERACTIVE_SELECTOR);
  if (control === null || control.closest("[data-sound-silent]") !== null) return;
  if (control.matches(":disabled, [aria-disabled='true']")) return;
  if (cues === undefined) {
    void ensureReady();
    setMasterVolume(0.32);
    cues = buildCues();
  }
  cues[cueFor(control)]();
}

document.addEventListener("click", onClick, true);

export function setSounds(next: boolean): void {
  on = next;
  try {
    localStorage.setItem(KEY, next ? "on" : "off");
  } catch {
    // Not remembered: this page still follows it.
  }
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether interaction sounds play. */
export function useSounds(): boolean {
  return useSyncExternalStore(subscribe, () => on);
}

/**
 * What the Context panel shows of a transcript (`components/pikit/context-panel.tsx`), read from pi-ai's JSON as it comes
 * (`unknown`): the images sent in it (`imagesOf`), and its sources (`sourcesOf`): what the web search
 * tool (`websearch`) and the fetch tool (`fetch`) returned, a card each (`ContextCards`' chunks). The
 * tools' text is read as they write it today (tool-websearch-brave, tool-fetch), defensively: what
 * does not parse is left out, never shown wrong. No imports: the kit's tests run it as it is.
 */

export interface SentImage {
  key: string;
  /** What an `<img>` shows: its URL, or its bytes as a `data:` URL. */
  src: string;
  mimeType?: string;
  /** Epoch ms of its message. */
  at?: number;
}

/** A source, as `ContextCards` shows it (its `ContextChunk`). */
export interface Source {
  key: string;
  title: string;
  meta?: string;
  body: string;
  source: string;
  href?: string;
  badge: string;
  tone: string;
}

type Fields = Record<string, unknown>;
const fields = (value: unknown): Fields => (typeof value === "object" && value !== null ? (value as Fields) : {});
const parts = (content: unknown): Fields[] => (Array.isArray(content) ? content.map(fields) : []);

/** The images of the person's messages (inline, or by URL), oldest first. */
export function imagesOf(messages: readonly unknown[]): SentImage[] {
  return messages.flatMap((each, i) => {
    const message = fields(each);
    if (message.role !== "user") return [];
    const at = typeof message.timestamp === "number" ? { at: message.timestamp } : {};
    return parts(message.content).flatMap((part, j) => {
      if (part.type !== "image") return [];
      const mimeType = typeof part.mimeType === "string" ? { mimeType: part.mimeType } : {};
      if (typeof part.url === "string") return [{ key: `${i}:${j}`, src: part.url, ...mimeType, ...at }];
      return typeof part.data === "string" && typeof part.mimeType === "string" ? [{ key: `${i}:${j}`, src: `data:${part.mimeType};base64,${part.data}`, ...mimeType, ...at }] : [];
    });
  });
}

const hostOf = (url: string): string => {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
};
const isWeb = (url: unknown): url is string => typeof url === "string" && /^https?:\/\/\S+$/i.test(url);
const textOf = (content: unknown): string => parts(content).flatMap((part) => (part.type === "text" && typeof part.text === "string" ? [part.text] : [])).join("\n");

/**
 * `websearch`'s results: blocks apart by a blank line, each `N. Title (age)`, then its address, then
 * its snippet, indented.
 */
function searchResults(text: string, key: string): Source[] {
  return text.split(/\n\s*\n/).flatMap((block, i) => {
    const match = /^\s*\d+\.\s+(.+)\n\s+(\S+)(?:\n\s+([\s\S]+))?$/.exec(block.trimEnd());
    const url = match?.[2];
    if (match === null || !isWeb(url)) return [];
    const host = hostOf(url);
    return [{ key: `${key}:${i}`, title: match[1]?.trim() || host, meta: `result ${i + 1}`, body: match[3]?.replace(/\s+/g, " ").trim() ?? "", source: host, href: url, badge: "WEB", tone: "bg-accent-blue" }];
  });
}

/**
 * `fetch`'s answer: `HTTP <status> <text> · <content type> · <final address>`, a blank line, then the
 * content (an HTML page as `# Title`, its text, then `Links:`).
 */
function fetched(text: string, key: string, asked: unknown): Source[] {
  const [head = "", ...rest] = text.split("\n");
  const columns = /^HTTP (\d{3})\b/.test(head) ? head.split(" · ") : [];
  const status = /^HTTP (\d{3})/.exec(columns[0] ?? "")?.[1];
  const url = [columns[2]?.trim(), asked].find(isWeb);
  if (status === undefined || url === undefined) return [];
  const type = (columns[1] ?? "").split(";")[0]?.trim().toLowerCase() ?? "";
  let content = rest.join("\n").trim();
  let title: string | undefined;
  if (content.startsWith("# ")) {
    const end = content.indexOf("\n");
    title = (end === -1 ? content.slice(2) : content.slice(2, end)).trim();
    content = end === -1 ? "" : content.slice(end + 1).trim();
  }
  content = content.split(/\n\s*\nLinks:\n/)[0] ?? "";
  const host = hostOf(url);
  const badge = type.includes("html") ? "HTML" : type.includes("json") ? "JSON" : "TXT";
  return [
    {
      key,
      title: title || host,
      meta: status === "200" ? `${content.length.toLocaleString()} characters` : `HTTP ${status}`,
      body: content.replace(/\s+/g, " ").slice(0, 400),
      source: host,
      href: url,
      badge,
      tone: badge === "HTML" ? "bg-green" : badge === "JSON" ? "bg-orange" : "bg-accent-blue",
    },
  ];
}

/** The sources of `messages`: what each web search and fetch returned, oldest first. Failed calls are left out. */
export function sourcesOf(messages: readonly unknown[]): Source[] {
  const args = new Map<unknown, Fields>();
  for (const each of messages) {
    const message = fields(each);
    if (message.role !== "assistant") continue;
    for (const part of parts(message.content)) if (part.type === "toolCall") args.set(part.id, fields(part.arguments));
  }
  return messages.flatMap((each, i) => {
    const message = fields(each);
    if (message.role !== "toolResult" || message.isError === true) return [];
    const text = textOf(message.content);
    if (message.toolName === "websearch") return searchResults(text, `s${i}`);
    if (message.toolName === "fetch") return fetched(text, `f${i}`, args.get(message.toolCallId)?.url);
    return [];
  });
}

/**
 * The theme: light, dark, or the system's (the default), remembered in this browser
 * (`localStorage["pikit-theme"]`). `public/theme.js` applies it before the first paint (no inline
 * script: the Content-Security-Policy); this module keeps `<html class="dark">` in step afterwards,
 * the system's changes included.
 */

import { useSyncExternalStore } from "react";

export type Theme = "light" | "dark" | "system";

const KEY = "pikit-theme";
const media = window.matchMedia("(prefers-color-scheme: dark)");
const listeners = new Set<() => void>();

function stored(): Theme {
  try {
    const value = localStorage.getItem(KEY);
    return value === "light" || value === "dark" ? value : "system";
  } catch {
    return "system";
  }
}

let theme = stored();

function apply(): void {
  const dark = theme === "dark" || (theme === "system" && media.matches);
  const root = document.documentElement;
  if (root.classList.contains("dark") === dark) return;
  // Every token flips at once: no transition while it does.
  root.classList.add("theme-switching");
  root.classList.toggle("dark", dark);
  requestAnimationFrame(() => requestAnimationFrame(() => root.classList.remove("theme-switching")));
}

media.addEventListener("change", apply);
apply();

export function setTheme(next: Theme): void {
  theme = next;
  try {
    if (next === "system") localStorage.removeItem(KEY);
    else localStorage.setItem(KEY, next);
  } catch {
    // Not remembered: this page still switches.
  }
  apply();
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The operator's choice (not what it resolves to). */
export function useTheme(): Theme {
  return useSyncExternalStore(subscribe, () => theme);
}

/**
 * A conversation's JSON, as whatever serves it gives it (the dashboard's admin API, channel-web's chat
 * API): its transcript's entries (`TranscriptEntry`, pi-durable's, newest first, paged) and its live
 * events (`LiveEvent`, pi-durable's, a `snapshot` first); and what its live view knows of them:
 * `reduce` folds each event into a `LiveState`. Pure: no React, no request.
 *
 * The stream starts with a `snapshot` and a client that fell behind gets a new one, so the state is
 * rebuilt from each snapshot, never from a count of events. What is written for good (entries) is read
 * from the transcript again: `changes` counts the times it changed. Until it is, `entries` holds the
 * ones the stream announced (a message ended, an entry appended), as the transcript gives them. An
 * answer that ended between two snapshots (a reconnect, a client that fell behind) is in `ended` (its
 * last partial) until the transcript has it.
 */

// Relative, not `@/`: scripts/dashboard.test.ts imports this module from outside the dashboard.
import type { AssistantMessage as Assistant, Message, RunningTool } from "./messages.ts";

/** One entry of a conversation's history: its messages in pi-ai's JSON (admin-api's `ApiTranscriptEntry`). */
export interface TranscriptEntry {
  id: string;
  /** `message`, `pi.reset`, …: the runtime's words. */
  kind: string;
  messages: unknown[];
}

/** One page of a transcript, newest first, and the cursor of the next (absent on the last page). */
export interface TranscriptPage {
  items: TranscriptEntry[];
  next?: string;
}

/** One live event of a conversation, in the runtime's JSON (admin-api's `ApiEvent`): a `snapshot` first. */
export interface LiveEvent {
  type: string;
  [field: string]: unknown;
}

export interface LiveState {
  connected: boolean;
  busy: boolean;
  /** The answer being written. */
  partial?: Assistant | undefined;
  tools: RunningTool[];
  /** The entries the stream announced, oldest first: the transcript's newest, maybe not read yet. */
  entries: TranscriptEntry[];
  /** Answers whose partial a snapshot no longer had (written for good meanwhile), as last seen, oldest first. */
  ended: Assistant[];
  /** Bumped whenever the transcript or the cost changed: read them again. */
  changes: number;
}

export const INITIAL: LiveState = { connected: false, busy: false, tools: [], entries: [], ended: [], changes: 0 };

/** Answers ended kept: the transcript has the older ones by now. */
const KEPT_ENDED = 5;

export type Action = { type: "reset" } | { type: "connected" } | { type: "disconnected" } | { type: "event"; event: LiveEvent };

/** An entry as the transcript gives it: pi-durable's, its model messages. */
function entryOf(value: unknown): TranscriptEntry | undefined {
  const entry = value as { id?: unknown; kind?: unknown; model?: unknown } | undefined;
  if (entry?.id === undefined) return undefined;
  return { id: String(entry.id), kind: String(entry.kind), messages: Array.isArray(entry.model) ? entry.model : [] };
}

/** The ones announced, the most recent kept: older ones are in the transcript read since. */
const KEPT_ENTRIES = 50;
const withEntry = (entries: TranscriptEntry[], value: unknown): TranscriptEntry[] => {
  const entry = entryOf(value);
  return entry === undefined || entries.some((each) => each.id === entry.id) ? entries : [...entries, entry].slice(-KEPT_ENTRIES);
};

type Change =
  | { type: "text_start" | "thinking_start" | "toolcall_start" | "block"; contentIndex: number; block: Assistant["content"][number] }
  | { type: "text_delta" | "thinking_delta"; contentIndex: number; delta: string }
  | { type: "toolcall_delta" }
  | { type: "message"; message: Assistant };

function applyChanges(partial: Assistant | undefined, changes: Change[]): Assistant | undefined {
  let message = partial;
  for (const change of changes) {
    if (change.type === "message") {
      message = change.message;
      continue;
    }
    if (message === undefined || change.type === "toolcall_delta") continue;
    const content = [...message.content];
    if ("delta" in change) {
      const part = content[change.contentIndex];
      if (part?.type === "text" && change.type === "text_delta") content[change.contentIndex] = { ...part, text: part.text + change.delta };
      if (part?.type === "thinking" && change.type === "thinking_delta") content[change.contentIndex] = { ...part, thinking: part.thinking + change.delta };
    } else {
      content[change.contentIndex] = change.block;
    }
    message = { ...message, content };
  }
  return message;
}

type ToolOutput = { trimStart?: number; append?: string } | { set: string };

export function reduce(state: LiveState, action: Action): LiveState {
  if (action.type === "reset") return INITIAL;
  if (action.type === "connected") return { ...state, connected: true };
  if (action.type === "disconnected") return { ...state, connected: false };
  const event = action.event;
  const changed = { ...state, changes: state.changes + 1 };
  switch (event.type) {
    case "snapshot": {
      const generation = event.generation as { message?: Assistant } | undefined;
      const tools = (event.tools as { callId: string; name: string; status: string; output?: string }[] | undefined) ?? [];
      const partial = generation?.message;
      // The answer being written is gone from this snapshot: it ended, and is shown as it was until the transcript has it.
      const gone = state.partial !== undefined && partial?.timestamp !== state.partial.timestamp ? state.partial : undefined;
      return {
        ...changed,
        busy: event.run !== undefined,
        partial,
        ended: gone === undefined ? state.ended : [...state.ended, gone].slice(-KEPT_ENDED),
        tools: tools.filter((tool) => tool.status !== "done").map((tool) => ({ callId: tool.callId, name: tool.name, output: tool.output ?? "" })),
      };
    }
    case "run_start":
      return { ...state, busy: true };
    case "run_end":
      return { ...changed, busy: false, partial: undefined, tools: [] };
    case "message_start": {
      const message = event.message as Message;
      return message.role === "assistant" ? { ...state, partial: message } : state;
    }
    case "message_update":
      return { ...state, partial: applyChanges(state.partial, event.changes as Change[]) };
    case "message_end":
      return { ...changed, partial: undefined, entries: withEntry(state.entries, event.entry) };
    case "tool_execution_start":
      return { ...state, tools: [...state.tools, { callId: String(event.toolCallId), name: String(event.toolName), output: "" }] };
    case "tool_execution_update": {
      const output = event.output as ToolOutput | undefined;
      if (output === undefined) return state;
      return {
        ...state,
        tools: state.tools.map((tool) => {
          if (tool.callId !== event.toolCallId) return tool;
          if ("set" in output) return { ...tool, output: output.set };
          return { ...tool, output: tool.output.slice(output.trimStart ?? 0) + (output.append ?? "") };
        }),
      };
    }
    case "tool_execution_end":
      return { ...changed, tools: state.tools.filter((tool) => tool.callId !== event.toolCallId) };
    case "entry_appended":
      return { ...changed, entries: withEntry(state.entries, event.entry) };
    case "usage_changed":
      return changed;
    default:
      return state;
  }
}
